const o = phi.observe({ maxElements: 300 });
const nodes = o.nodes.map(n=>`${n.ref}. ${n.role} "${(n.name||n.text||'').slice(0,50)}" ${n.href||''}`);
return { total: o.total, hasPeriod: nodes.filter(s=>/time|year|month|week|period|Replies/i.test(s)), tail: nodes.slice(-40) };

const links = phi.query("a", { fields: ["href"], limit: 400 });
const periods = links.items.filter(i => i.href && /period=|top\?/.test(i.href));
const texts = phi.query("ul.nav-pills li, .period, .top-period", { limit: 60 });
return { periods: periods.slice(0,40), texts: texts.items.map(t=>t.text).slice(0,40), total: links.total };

phi.goto("https://discussions.flightaware.com/top?period=all");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 8000 });
const o = phi.observe({ maxElements: 200 });
const nodes = o.nodes.slice(0,40).map(n=>`${n.ref}. ${n.role} "${(n.name||n.text||'').slice(0,50)}"`);
return { url: o.url, nodes };

const before = phi.query(".topic-list tbody tr", { limit: 5 });
const c = phi.click(9);
phi.waitForNetworkIdle({ idleMs: 600, timeoutMs: 6000 });
const rows = phi.query(".topic-list tbody tr", { fields: ["data-topic-id"], limit: 5 });
const first = phi.query(".topic-list tbody tr:first-child a.raw-topic-link, .topic-list tbody tr:first-child a.title", { fields: ["href"], limit: 3 });
return { clicked: c.changed, before: before.items.map(r=>r.text), after: rows.items.map(r=>r.text), firstLinks: first.items };

phi.goto("https://discussions.flightaware.com/top?ascending=false&order=posts&period=all");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 10000 });
const rows = phi.query(".topic-list tbody tr", { fields: ["data-topic-id"], limit: 40 });
const firstRow = phi.query(".topic-list tbody tr:first-child a.title, .topic-list tbody tr:first-child a.raw-topic-link", { fields: ["href"], limit: 3 });
const sortState = phi.query(".topic-list th", { limit: 10 });
return { url: phi.tabs.list ? undefined : undefined, rows: rows.items.slice(0,10).map(r=>r.text), firstRow: firstRow.items, headers: sortState.items.map(s=>s.text) };

const c = phi.click('.topic-list tbody tr:first-child a.title');
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 10000 });
const head = phi.query('h1', { limit: 2 });
const counts = phi.query('.topic-post, .topic-map', { limit: 3 });
return { result: { url: c.url, navigated: c.navigated }, title: head.items.map(h=>h.text), text: phi.text().slice(0, 900) };

const url = phi.tabs.list().find(t => t.url.includes("discussions.flightaware.com/t/"))?.url;
const title = phi.query("h1", { limit: 2 }).items.map(h => h.text);
const map = phi.query(".topic-map, .topic-map--op .topic-map__contents", { limit: 2 }).items.map(i => i.text);
const cat = phi.query("a.badge-category__name, .topic-category a", { limit: 2 }).items.map(i => i.text);
const posts = phi.js(() => {
  const d = document.querySelector('#topic-title, h1')?.textContent?.trim();
  const meta = document.querySelector('.topic-post .topic-avatar')?.textContent || '';
  return { docTitle: document.title, postCountText: (document.body.innerText.match(/\d[\d,]*\s*(repl|posts)/i) || [])[0] || null, h1: d };
});
phi.keep("thread", { name: title[0], url, category: cat, topicMap: map.slice(0,1), docTitle: posts.docTitle });
return { url, title, map, cat, posts };

const info = phi.js(() => {
  const txt = document.body.innerText;
  const replies = (txt.match(/([\d.,k]+)\s*repl(?:y|ies)/i) || [])[1] || null;
  const postNums = Array.from(document.querySelectorAll('.topic-post')).map(p => p.id);
  const counter = document.querySelector('.topic-post .post-number, .topic-post__count');
  const lastPost = document.querySelectorAll('.topic-post');
  const firstNum = lastPost[0]?.querySelector('.topic-post__count, .number')?.textContent?.trim();
  const shareBtn = document.querySelector('.topic-share .topic-share-menu button, .share-and-invite button');
  const titleLink = document.querySelector('h1');
  return {
    title: document.title,
    repliesMatch: replies,
    firstPostNumber: firstNum,
    snippet: txt.slice(0, 400),
    headerBits: Array.from(document.querySelectorAll('.topic-map__num, .topic-map__stats span, .number')).slice(0,12).map(e=>e.textContent.trim()).filter(Boolean)
  };
});
const obs = phi.observe({ maxElements: 40 });
return { info, sample: obs.nodes.slice(0,15).map(n=>`${n.ref} ${n.role} ${n.name||''}`) };

phi.narrate("double-checking the all-time list, sorted by replies, before wrapping up");
phi.goto("https://discussions.flightaware.com/top?ascending=false&order=posts&period=all");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 12000 });
const rows = phi.query('.topic-list tbody tr', { limit: 6 });
const first = phi.query('th[data-sort-order], .topic-list th', { limit: 8 }).items.map(i=>i.text.replace(/\s+/g,' ').trim());
const active = phi.js(() => {
  const cur = document.querySelector('.period-chooser .btn .d-icon, .period-chooser button span');
  const sel = Array.from(document.querySelectorAll('.period-chooser .btn, .topic-list th')).map(e=>e.textContent.replace(/\s+/g,' ').trim()).filter(Boolean).slice(0,10);
  const path = location.href;
  return { path, sel };
});
phi.keep("toplist", { url: active.path, headers: first, rows: rows.items.map(r=>r.text.replace(/\s+/g,' ').trim()) });
return { url: active.path, headers: first, rows: rows.items.map(r=>r.text.replace(/\s+/g,' ').trim()) };

const obs = phi.observe({ maxElements: 60 });
const rows = phi.query('.topic-list tbody tr', { fields: ["class"], limit: 5 });
const info = phi.js(() => {
  const chooser = Array.from(document.querySelectorAll('.period-chooser .btn, .nav-pills a, .topic-list th')).map(e => (e.textContent || '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 12);
  const activeSort = Array.from(document.querySelectorAll('.topic-list th')).map(th => ({ t: (th.textContent||'').replace(/\s+/g,' ').trim(), cls: th.className }));
  const firstRow = document.querySelector('.topic-list tbody tr');
  const cells = firstRow ? Array.from(firstRow.querySelectorAll('td, th')).map(c => (c.textContent||'').replace(/\s+/g,' ').trim()).filter(Boolean) : [];
  const firstLink = firstRow?.querySelector('a.title, a.raw-topic-link')?.getAttribute('href');
  return { path: location.href, chooser, activeSort, firstRowCells: cells, firstLink };
});
return { url: info.path, chooser: info.chooser, activeSort: info.activeSort, firstRowCells: info.firstRowCells, firstLink: info.firstLink, totalRows: rows.total };

phi.narrate("opening the all-time most-replied thread to land on it");
const info = phi.goto("https://discussions.flightaware.com/t/the-banter-thread/4412");
phi.waitForNetworkIdle({ idleMs: 800, timeoutMs: 15000 });
const detail = phi.js(() => {
  const clean = s => (s || '').replace(/\s+/g, ' ').trim();
  const map = document.querySelector('.topic-map');
  const mapText = clean(map ? map.innerText : '');
  const h1 = clean(document.querySelector('h1')?.innerText);
  const head = clean(document.body.innerText).slice(0, 300);
  const posts = document.querySelectorAll('.topic-post').length;
  return { url: location.href, title: document.title, h1, mapText, posts, head };
});
phi.keep("thread_final", {
  url: detail.url,
  title: detail.h1,
  topicMap: detail.mapText.slice(0, 300),
});
return detail;

const info = phi.js(() => {
  const clean = s => (s || '').replace(/\s+/g, ' ').trim();
  const t = document.title;
  const tl = document.querySelector('.topic-timeline, .timeline-container');
  const tlText = clean(tl ? tl.innerText : '');
  const replies = Array.from(document.querySelectorAll('[title], .posts, .replies, .topic-map')).map(e => clean(e.innerText || '')).filter(s => /repl/i.test(s)).slice(0, 6);
  const header = clean(document.querySelector('#topic-title, .title-wrapper')?.innerText || '');
  const lastReply = clean(document.querySelector('.topic-status-info, .topic-timeline .timeline-date')?.innerText || '');
  return { url: location.href, title: t, header, timeline: tlText.slice(0, 400), replyish: replies, lastReply };
});
phi.keep("thread_final", { url: info.url, title: info.title, header: info.header, timeline: info.timeline, replyish: info.replyish });
return info;

